#include <stdio.h>
#include <stdlib.h>
int main(int argc, char *argv[]) {
    if (argc != 2) return 1;
    long n = atol(argv[1]);
    if (n <= 0) {
        printf("0\n");
    } else if (n == 1) {
        printf("1\n");
    } else {
        long a = 0, b = 1;
        for (long i = 2; i <= n; i++) {
            long temp = a + b;
            a = b;
            b = temp;
        }
        printf("%ld\n", b);
    }
    return 0;
}
